def underwater_series(values):
    drawdowns = []
    days = []
    peak = None
    at = 0
    for t, v in enumerate(values):
        if peak is None or v >= peak:
            peak = v
            at = t
        drawdowns.append(v / peak - 1)
        days.append(t - at + 1 if t > at else 0)
    return (drawdowns, days)
